    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    day = day_context['day']
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opps = []
    prev_bids = []
    urgent_opp_count = 0
    rich_opp_pressure = 0.0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 2:
                urgent_opp_count += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = float(prev.get('bid', 0.0))
                prev_bids.append(bid)
                if opp.get('budget', 0) > budget * 0.8:
                    rich_opp_pressure = max(rich_opp_pressure, bid)

    if not alive_opps:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    units = int(supply / WATER_REQ)
    scarcity = units <= 1
    severe_scarcity = float(supply) <= 16.0

    danger = hp <= 3 or no_water_days >= 2
    caution = hp <= 5 or no_water_days >= 1

    if danger:
        base = max(92.0, highest_prev + 8.0)
        if severe_scarcity:
            base = max(base, 118.0)
        if rich_opp_pressure >= 120.0:
            base = max(base, rich_opp_pressure + 3.0)
        return float(min(budget, base))

    if scarcity:
        if highest_prev >= 140.0:
            bid = 34.0 if hp >= 7 and no_water_days == 0 else 96.0
            return float(min(budget, bid))
        if highest_prev >= 85.0:
            bid = 42.0 if hp >= 8 and no_water_days == 0 else highest_prev + 4.0
            return float(min(budget, bid))

        bid = 48.0
        if caution:
            bid = 72.0
        if urgent_opp_count >= 2:
            bid += 10.0
        if severe_scarcity:
            bid += 8.0
        return float(min(budget, bid))

    bid = 22.0
    if caution:
        bid = 38.0
    if avg_prev > 60.0:
        bid = max(bid, min(58.0, avg_prev * 0.75))
    if day >= 8 and hp <= 6:
        bid = max(bid, 55.0)

    return float(min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Alive opponents
    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    # If no one alive, bid minimal to conserve budget
    if not alive_opps:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    # Read yesterday bids from previous_trace only
    prev_bids = []
    prev_hp_after = []
    for oid, o in alive_opps:
        pt = o.get('previous_trace', {})
        if pt and pt.get('bid') is not None:
            try:
                prev_bids.append(float(pt['bid']))
                prev_hp_after.append(float(pt.get('hp_after', o.get('hp', 0))))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    # Also estimate how many were pressured: count of very high bids
    high_bid_count = 0
    for b in prev_bids:
        if b >= DAILY_SALARY * 1.2:
            high_bid_count += 1

    # Determine target bid based on supply pressure and opponent aggression
    # If supply is low, we must secure water more reliably.
    # supply_range is [15,25]; water allocation likely depends on bid.
    supply_ratio = 0.0
    try:
        supply_ratio = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    except Exception:
        supply_ratio = 0.5

    # Base aggressiveness: mid-tier
    # At low supply_ratio -> bid higher.
    base = DAILY_SALARY * (0.62 + (1.0 - supply_ratio) * 0.25)

    # If someone already went very high yesterday, avoid full matching but respond if my HP is low.
    if highest_prev_bid >= DAILY_SALARY * 1.5:
        if my_status['hp'] <= 2:
            target = DAILY_SALARY * 0.95
        elif my_status['hp'] <= 4:
            target = max(base, DAILY_SALARY * 0.75)
        else:
            # Don't overpay; try to win with slightly above base
            target = max(base, DAILY_SALARY * 0.68)
    else:
        # Moderate bids yesterday: bid near base.
        if my_status['hp'] <= 2:
            target = max(base, DAILY_SALARY * 0.9)
        elif my_status['hp'] <= 4:
            target = max(base, DAILY_SALARY * 0.75)
        else:
            target = base

    # If my no_water_days is high, I must secure water now.
    no_water_days = int(my_status.get('no_water_days', 0))
    if no_water_days >= 2:
        target = max(target, DAILY_SALARY * 0.9)
    if no_water_days >= 3:
        target = max(target, DAILY_SALARY * 1.05)

    # Budget cap
    budget = float(my_status.get('budget', 0.0))
    if budget <= 0:
        return 0.0

    # Ensure we don't bid above what we can pay
    bid = min(budget, target)

    # Small adjustment: if multiple opponents bid high yesterday, slightly increase
    if high_bid_count >= 2:
        bid = min(budget, bid * 1.08)

    # Keep bid non-negative
    if bid < 0:
        bid = 0.0

    return float(bid)

