        base_bid = DAILY_SALARY * 0.35
        if supply <= 18:
            base_bid = DAILY_SALARY * 0.5
        bid = min(my_budget, base_bid)

    # Ensure bid is within budget and non-negative
    bid = max(0.0, min(my_budget, bid))
